-- Migration: Import RSUD drug catalog (TARIF_OBAT) and stock logs (STOK_OBAT)
-- Generated from TARIF_OBAT.sql (1597 drugs) and STOK_OBAT.sql (548 stock logs)

-- 1. Ensure required columns exist on public.drugs
ALTER TABLE public.drugs
  ADD COLUMN IF NOT EXISTS code TEXT,
  ADD COLUMN IF NOT EXISTS batch_no TEXT,
  ADD COLUMN IF NOT EXISTS description TEXT,
  ADD COLUMN IF NOT EXISTS obat_id BIGINT;

CREATE INDEX IF NOT EXISTS idx_drugs_name ON public.drugs (name);
CREATE INDEX IF NOT EXISTS idx_drugs_code ON public.drugs (code);
CREATE INDEX IF NOT EXISTS idx_drugs_category ON public.drugs (category);
CREATE INDEX IF NOT EXISTS idx_drugs_is_active ON public.drugs (is_active);

-- 2. Safely clear old seed drug data (keep any drug already referenced by prescriptions/sales)
DELETE FROM public.drug_stock_logs;

DELETE FROM public.drugs
WHERE drug_id NOT IN (
  SELECT DISTINCT drug_id FROM public.prescription_items
  UNION
  SELECT DISTINCT drug_id FROM public.free_drug_sale_items
);

UPDATE public.drugs
SET is_active = false
WHERE drug_id LIKE 'DRG-%';

-- 3. Insert / upsert all 1597 drugs from TARIF_OBAT
